    {
      "id": "top-5-trending-repos",
      "title": "hermes-agent Leads with 1,347 Stars — Top 5 Repos by Total Score",
      "objective": "Present a ranked table or horizontal bar chart of the top 5 trending repos (hermes-agent, graphify, awesome-design-md, caveman, claude-code-best-practice) with stars, forks, pushes, and PRs. Highlight the dominant lead of #1."
    },
    {
      "id": "language-distribution",
      "title": "Python and TypeScript Dominate Trending Repos' Language Mix",
