                --h2-size: clamp(0.9rem, 2.5vw, 1.25rem);
                --body-size: clamp(0.65rem, 1vw, 0.85rem);
            }
        }

        @media (max-width: 600px) {
            :root { --title-size: clamp(1.25rem, 7vw, 2.5rem); }
        }

        @media (prefers-reduced-motion: reduce) {
            *, *::before, *::after {
                animation-duration: 0.01ms !important;
                transition-duration: 0.2s !important;
            }
            html { scroll-behavior: auto; }
        }

        /* ============================================
           GLOBAL SHARED ELEMENTS
           ============================================ */

        /* Grid scanline background */
        .grid-bg::before {
            content: '';
            position: absolute;
            inset: 0;
            background-image:
                linear-gradient(rgba(57,211,83,0.025) 1px, transparent 1px),
                linear-gradient(90deg, rgba(57,211,83,0.025) 1px, transparent 1px);
            background-size: 40px 40px;
            pointer-events: none;
            z-index: 0;
        }

        /* Slide label (top-left corner prompt style) */
        .slide-label {
            position: absolute;
            top: clamp(1rem, 2.5vh, 2rem);
            left: var(--slide-padding);
            font-size: var(--small-size);
            color: var(--accent-green);
            opacity: 0.7;
            letter-spacing: 0.08em;
            z-index: 10;
        }

        /* Slide number (top-right) */
        .slide-number {
            position: absolute;
            top: clamp(1rem, 2.5vh, 2rem);
            right: var(--slide-padding);
            font-size: var(--small-size);
            color: var(--text-muted);
            letter-spacing: 0.06em;
            z-index: 10;
        }

        /* Data source footer */
        .source-footer {
            position: absolute;
            bottom: clamp(0.75rem, 2vh, 1.5rem);
            right: var(--slide-padding);
            font-size: clamp(0.55rem, 0.85vw, 0.72rem);
            color: var(--text-muted);
            letter-spacing: 0.04em;
        }

        /* === REVEAL ANIMATIONS === */
        .reveal {
            opacity: 0;
            transform: translateY(20px);
            transition: opacity var(--duration-normal) var(--ease-out-expo),
                        transform var(--duration-normal) var(--ease-out-expo);
        }
        .slide.visible .reveal { opacity: 1; transform: translateY(0); }
        .reveal-left {
            opacity: 0;
            transform: translateX(-30px);
            transition: opacity var(--duration-normal) var(--ease-out-expo),
                        transform var(--duration-normal) var(--ease-out-expo);
        }
        .slide.visible .reveal-left { opacity: 1; transform: translateX(0); }
        .reveal-scale {
            opacity: 0;
            transform: scale(0.94);
            transition: opacity var(--duration-normal) var(--ease-out-expo),
                        transform var(--duration-normal) var(--ease-out-expo);
        }
        .slide.visible .reveal-scale { opacity: 1; transform: scale(1); }

        /* Stagger delays */
        .d1 { transition-delay: 0.05s; }
        .d2 { transition-delay: 0.15s; }
        .d3 { transition-delay: 0.25s; }
        .d4 { transition-delay: 0.35s; }
        .d5 { transition-delay: 0.45s; }
        .d6 { transition-delay: 0.55s; }
        .d7 { transition-delay: 0.65s; }
        .d8 { transition-delay: 0.75s; }

        /* === PROGRESS BAR === */
        .progress-bar {
            position: fixed;
            top: 0;
            left: 0;
            height: 2px;
            background: var(--accent-green);
            box-shadow: 0 0 8px var(--accent-green-glow);
            z-index: 1000;
            transition: width 0.3s var(--ease-in-out);
            width: 0%;
        }

        /* === NAV DOTS === */
        .nav-dots {
            position: fixed;
            right: clamp(0.75rem, 1.5vw, 1.5rem);
            top: 50%;
            transform: translateY(-50%);
            display: flex;
            flex-direction: column;
            gap: clamp(0.35rem, 0.8vh, 0.65rem);
            z-index: 100;
        }
        .nav-dot {
            width: 6px;
            height: 6px;
            border-radius: 50%;
            background: var(--text-muted);
            cursor: pointer;
            transition: all 0.3s ease;
            border: none;
        }
        .nav-dot.active {
            background: var(--accent-green);
            box-shadow: 0 0 6px var(--accent-green-glow);
            transform: scale(1.4);
        }

        /* ============================================
           SLIDE 1: TITLE SLIDE
           ============================================ */
        .slide-title {
            background: var(--bg-primary);
        }

        .title-bg-glow {
            position: absolute;
            width: 60vw;
            height: 60vh;
            border-radius: 50%;
            background: radial-gradient(ellipse, rgba(57,211,83,0.07) 0%, transparent 70%);
            top: 50%;
            left: 50%;
            transform: translate(-50%, -50%);
            pointer-events: none;
            animation: pulseGlow 4s ease-in-out infinite;
        }
        @keyframes pulseGlow {
            0%, 100% { opacity: 0.6; transform: translate(-50%, -50%) scale(1); }
            50% { opacity: 1; transform: translate(-50%, -50%) scale(1.05); }
        }

        .title-corner-tl {
            position: absolute;
            top: 0; left: 0;
            width: clamp(60px, 10vw, 120px);
            height: clamp(60px, 10vh, 120px);
            border-top: 1.5px solid var(--accent-green);
            border-left: 1.5px solid var(--accent-green);
            opacity: 0.4;
        }
        .title-corner-br {
            position: absolute;
            bottom: 0; right: 0;
            width: clamp(60px, 10vw, 120px);
            height: clamp(60px, 10vh, 120px);
            border-bottom: 1.5px solid var(--accent-green);
            border-right: 1.5px solid var(--accent-green);
            opacity: 0.4;
        }

        .title-inner {
            position: relative;
            z-index: 2;
            display: flex;
            flex-direction: column;
            gap: clamp(0.6rem, 1.8vh, 1.5rem);
        }

        .title-prompt {
            font-size: var(--small-size);
            color: var(--accent-green);
            opacity: 0.8;
            letter-spacing: 0.1em;
        }
        .title-prompt::before { content: '$ '; }

        .title-h1 {
            font-size: var(--title-size);
            font-weight: 800;
            line-height: 1.1;
            color: var(--text-primary);
            letter-spacing: -0.02em;
        }
