<script>
    /* ============================================
       DONUT CHART BUILDER — Slide 4
       Draws SVG segments from the language data
       ============================================ */
    (function buildDonut() {
        const data = [
            { label: 'Python',       count: 7, color: '#39d353' },
            { label: 'TypeScript',   count: 4, color: '#58a6ff' },
            { label: 'HTML',         count: 2, color: '#e3b341' },
            { label: 'Rust',         count: 2, color: '#bc8cff' },
            { label: 'Swift',        count: 2, color: '#ffa657' },
            { label: 'Shell',        count: 1, color: '#f85149' },
            { label: 'Java',         count: 1, color: '#56d364' },
            { label: 'Unspecified',  count: 1, color: '#484f58' },
        ];

        const total = data.reduce((s, d) => s + d.count, 0);
        const cx = 100, cy = 100, r = 80, innerR = 52;
        let startAngle = 0;

        const svg = document.getElementById('donutChart');

        data.forEach(d => {
            const angle = (d.count / total) * 2 * Math.PI;
            const endAngle = startAngle + angle;

            const x1 = cx + r * Math.cos(startAngle);
            const y1 = cy + r * Math.sin(startAngle);
            const x2 = cx + r * Math.cos(endAngle);
            const y2 = cy + r * Math.sin(endAngle);
            const ix1 = cx + innerR * Math.cos(startAngle);
            const iy1 = cy + innerR * Math.sin(startAngle);
            const ix2 = cx + innerR * Math.cos(endAngle);
            const iy2 = cy + innerR * Math.sin(endAngle);

            const large = angle > Math.PI ? 1 : 0;

            const path = document.createElementNS('http://www.w3.org/2000/svg', 'path');
            path.setAttribute('d', [
                `M ${x1} ${y1}`,
                `A ${r} ${r} 0 ${large} 1 ${x2} ${y2}`,
                `L ${ix2} ${iy2}`,
                `A ${innerR} ${innerR} 0 ${large} 0 ${ix1} ${iy1}`,
                'Z'
            ].join(' '));
            path.setAttribute('fill', d.color);
            path.setAttribute('opacity', '0.9');
            path.setAttribute('stroke', '#0d1117');
            path.setAttribute('stroke-width', '1.5');

            /* Hover tooltip */
            const title = document.createElementNS('http://www.w3.org/2000/svg', 'title');
            title.textContent = `${d.label}: ${d.count} repos (${Math.round(d.count/total*100)}%)`;
            path.appendChild(title);

            svg.appendChild(path);
            startAngle = endAngle;
        });
    })();

    /* ============================================
       SLIDE PRESENTATION CONTROLLER
       Handles: keyboard nav, touch, progress bar, nav dots
       ============================================ */
    class SlidePresentation {
        constructor() {
            this.slides = Array.from(document.querySelectorAll('.slide'));
            this.currentIndex = 0;
            this.totalSlides = this.slides.length;
            this.isScrolling = false;
            this.touchStartY = 0;

            this.setupIntersectionObserver();
            this.setupKeyboardNav();
            this.setupTouchNav();
            this.setupWheelNav();
            this.setupProgressBar();
            this.buildNavDots();

            /* Trigger first slide immediately */
            this.slides[0].classList.add('visible');
            this.updateProgress(0);
        }

        /* Intersection Observer — adds .visible when slide enters viewport (triggers animations) */
        setupIntersectionObserver() {
            const observer = new IntersectionObserver(entries => {
                entries.forEach(entry => {
                    if (entry.isIntersecting) {
                        entry.target.classList.add('visible');
                        const idx = this.slides.indexOf(entry.target);
                        if (idx !== -1) {
                            this.currentIndex = idx;
                            this.updateProgress(idx);
                            this.updateNavDots(idx);
                        }
                    }
                });
            }, { threshold: 0.5 });

            this.slides.forEach(s => observer.observe(s));
        }

        /* Navigate to a specific slide index */
        goTo(idx) {
            if (idx < 0 || idx >= this.totalSlides) return;
            this.slides[idx].scrollIntoView({ behavior: 'smooth' });
        }

        /* Keyboard: arrows, space, page keys */
        setupKeyboardNav() {
            document.addEventListener('keydown', e => {
                switch (e.key) {
                    case 'ArrowDown': case 'ArrowRight': case ' ':
                        e.preventDefault();
                        this.goTo(this.currentIndex + 1);
                        break;
                    case 'ArrowUp': case 'ArrowLeft':
                        e.preventDefault();
                        this.goTo(this.currentIndex - 1);
                        break;
                    case 'PageDown':
                        e.preventDefault();
                        this.goTo(this.currentIndex + 1);
                        break;
                    case 'PageUp':
                        e.preventDefault();
                        this.goTo(this.currentIndex - 1);
                        break;
                    case 'Home':
                        e.preventDefault();
                        this.goTo(0);
                        break;
                    case 'End':
                        e.preventDefault();
                        this.goTo(this.totalSlides - 1);
                        break;
                }
            });
        }

        /* Touch/swipe support */
        setupTouchNav() {
            document.addEventListener('touchstart', e => {
                this.touchStartY = e.touches[0].clientY;
            }, { passive: true });

            document.addEventListener('touchend', e => {
                const diff = this.touchStartY - e.changedTouches[0].clientY;
                if (Math.abs(diff) > 50) {
                    diff > 0 ? this.goTo(this.currentIndex + 1) : this.goTo(this.currentIndex - 1);
                }
            }, { passive: true });
        }

        /* Mouse wheel navigation (debounced) */
        setupWheelNav() {
            let last = 0;
            document.addEventListener('wheel', e => {
                const now = Date.now();
                if (now - last < 800) return;
                last = now;
                e.deltaY > 0 ? this.goTo(this.currentIndex + 1) : this.goTo(this.currentIndex - 1);
            }, { passive: true });
        }

        /* Progress bar */
        setupProgressBar() {
            this.progressBar = document.getElementById('progressBar');
        }

        updateProgress(idx) {
            if (!this.progressBar) return;
            const pct = this.totalSlides <= 1 ? 100 : (idx / (this.totalSlides - 1)) * 100;
            this.progressBar.style.width = pct + '%';
        }

        /* Navigation dots */
        buildNavDots() {
            const nav = document.getElementById('navDots');
            if (!nav) return;
            this.slides.forEach((_, i) => {
                const btn = document.createElement('button');
                btn.className = 'nav-dot' + (i === 0 ? ' active' : '');
                btn.setAttribute('aria-label', `Go to slide ${i + 1}`);
                btn.addEventListener('click', () => this.goTo(i));
                nav.appendChild(btn);
            });
        }

        updateNavDots(idx) {
            const dots = document.querySelectorAll('.nav-dot');
            dots.forEach((d, i) => d.classList.toggle('active', i === idx));
        }
    }

    /* Boot the presentation */
    document.addEventListener('DOMContentLoaded', () => {
        new SlidePresentation();
    });
</script>
</body>
</html>
