        for x_frac in (0.25, 0.5, 0.75):
            for y_frac in (0.25, 0.5, 0.75):
                px = int(curr_img.width * x_frac)
                py = int(curr_img.height * y_frac)
                if curr_img.getpixel((px, py)) != prev_img.getpixel((px, py)):
