arguments.command:
cat > /tmp/capture_slides.cjs << 'EOF'
const { chromium } = require('playwright');
const path = require('path');
const http = require('http');
const fs = require('fs');

const htmlFile = '/app/output/presentation.html';
const outDir = '/tmp/slide_captures';
const width = 1920;
const height = 1080;

if (!fs.existsSync(outDir)) fs.mkdirSync(outDir, { recursive: true });

// Start simple HTTP server
const serveDir = path.dirname(htmlFile);
const server = http.createServer((req, res) => {
    const filePath = path.join(serveDir, req.url === '/' ? 'presentation.html' : req.url);
    try {
        const content = fs.readFileSync(filePath);
        res.writeHead(200);
        res.end(content);
    } catch(e) {
        res.writeHead(404);
        res.end('Not found');
    }
});

server.listen(0, '127.0.0.1', async () => {
    const port = server.address().port;
    const url = `http://127.0.0.1:${port}/presentation.html`;

    const browser = await chromium.launch({ 
        executablePath: process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE_PATH || undefined 
    });
    const page = await browser.newPage();
    await page.setViewportSize({ width, height });
    await page.goto(url, { waitUntil: 'networkidle' });
    await page.waitForTimeout(800);

    // Count slides
    const slideCount = await page.$$eval('.slide', els => els.length);
    console.log(`Found ${slideCount} slides`);

    for (let i = 0; i < slideCount; i++) {
        // Jump directly to each slide by scrolling to its position
        await page.evaluate((idx) => {
            const slides = document.querySelectorAll('.slide');
            if (slides[idx]) {
                // Instant scroll — bypass smooth CSS
                const top = slides[idx].getBoundingClientRect().top + window.scrollY;
                window.scrollTo({ top, behavior: 'instant' });
            }
        }, i);
        await page.waitForTimeout(400);

        const idx = String(i + 1).padStart(3, '0');
        const imgPath = `${outDir}/slide_${idx}.png`;
        await page.screenshot({ path: imgPath });
        console.log(`Captured slide ${i+1} → ${imgPath}`);
    }

    await browser.close();
    server.close();
});
EOF
NODE_PATH=/usr/local/lib/node_modules:/app/node_modules PLAYWRIGHT_BROWSERS_PATH=/ms-playwright node /tmp/capture_slides.cjs 2>&1

